import 'package:flutter/material.dart';

class Contatore extends StatefulWidget {
  const Contatore({super.key});

  @override
  State<Contatore> createState() => _ContatoreState();
}

class _ContatoreState extends State<Contatore> {
  int _valore = 0;

  void _incrementa() => setState(() => _valore++);
  void _decrementa() => setState(() => _valore--);

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text('Valore: $_valore', style: TextStyle(fontSize: 32)),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton(onPressed: _decrementa, child: Text('-')),
            SizedBox(width: 16),
            ElevatedButton(onPressed: _incrementa, child: Text('+')),
          ],
        ),
      ],
    );
  }
}

