class BadgeNotifica extends StatelessWidget {
  final int count;

  const BadgeNotifica({required this.count});

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        Icon(Icons.notifications, size: 32),
        if (count > 0)
          Positioned(
            right: 0,
            top: 0,
            child: Container(
              padding: EdgeInsets.all(4),
              decoration: BoxDecoration(
                color: Colors.red,
                shape: BoxShape.circle,
              ),
              child: Text('$count', style: TextStyle(color: Colors.white, fontSize: 10)),
            ),
          ),
      ],
    );
  }
}

